    template: `<span class="pill legacy" [class]="variant">{{ label }}@if (!disableTooltip) {<span class="hint">i</span>}</span>`
})
export class PillLegacyComponent {
    @Input() label = "";
    @Input() variant: PillVariant = "info";
    @Input() disableTooltip = false;
}

