import { readFileSync, writeFileSync } from "node:fs";
import { globSync } from "node:fs";

const WRITE = process.argv.includes("--write");
const ROOT = "workspace/src";

const files = globSync("**/*.{ts,html,css}", { cwd: ROOT }).map(f => ROOT + "/" + f.replaceAll("\\", "/"));

// Tags whose component inherits the renamed input from PillComponent.
const TAGS = ["app-fancy-pill", "app-status-pill"];
const tagRe = new RegExp(`<(${TAGS.join("|")})\\b((?:[^>"']|"[^"]*"|'[^']*')*?)(\\/?)>`, "g");
const attrRe = /([^\s=/>]+)(\s*=\s*(?:"[^"]*"|'[^']*'|[^\s>]*))?/g;

let edits = 0, touched = [];
const leftovers = [];

for (const file of files) {
    const orig = readFileSync(file, "utf8");
    let out = orig;

    out = out.replace(tagRe, (m, tag, attrs, slash) => {
        const newAttrs = attrs.replace(attrRe, (am, name, rest) => {
            if (name === "disableTooltip") { edits++; return "hideHint" + (rest ?? ""); }
            if (name === "[disableTooltip]") { edits++; return "[hideHint]" + (rest ?? ""); }
            return am;
        });
        return `<${tag}${newAttrs}${slash}>`;
    });

    if (out !== orig) touched.push(file);
    if (WRITE && out !== orig) writeFileSync(file, out);

    // report remaining occurrences for manual review
    out.split("\n").forEach((line, i) => {
        if (line.includes("disableTooltip")) leftovers.push(`${file}:${i + 1}  ${line.trim().slice(0, 150)}`);
    });
}

console.log(`${edits} attribute edits in ${touched.length} files (${WRITE ? "written" : "dry run"})`);
console.log(`--- ${leftovers.length} remaining occurrences:`);
const byKind = new Map();
for (const l of leftovers) {
    const key = /app-card|app-pill-legacy/.test(l) ? "card-or-legacy-tag" : "OTHER";
    byKind.set(key, (byKind.get(key) ?? 0) + 1);
    if (key === "OTHER") console.log(l);
}
console.log([...byKind]);

