npx ngc -p tsconfig.json 2>&1 | grep -E "^.\[96m" | sed -e 's/\x1b\[[0-9;]*m//g' | sed -e 's/ - error.*//' > /tmp/errs.txt && cat > /tmp/fixerrs.mjs <<'EOF'
import { readFileSync, writeFileSync } from "node:fs";
const errs = readFileSync("/tmp/errs.txt", "utf8").trim().split("\n");
const byFile = new Map();
for (const e of errs) {
    const m = e.match(/^(.*):(\d+):(\d+)$/);
    if (!m) throw new Error("bad: " + e);
    if (!byFile.has(m[1])) byFile.set(m[1], []);
    byFile.get(m[1]).push([+m[2], +m[3]]);
}
let n = 0;
for (const [file, locs] of byFile) {
    const lines = readFileSync(file, "utf8").split("\n");
    // descending by col so earlier edits don't shift later ones
    locs.sort((a, b) => b[0] - a[0] || b[1] - a[1]);
    for (const [ln, col] of locs) {
        const line = lines[ln - 1];
        const at = col - 1;
        if (line.slice(at, at + 14) !== "disableTooltip") throw new Error(`mismatch ${file}:${ln}:${col} -> ${JSON.stringify(line.slice(at, at + 20))}`);
        lines[ln - 1] = line.slice(0, at) + "hideHint" + line.slice(at + 14);
        n++;
    }
    writeFileSync(file, lines.join("\n"));
}
console.log(`${n} reads renamed in ${byFile.size} files`);
EOF
node /tmp/fixerrs.mjs

