import { readFileSync, writeFileSync, globSync } from "node:fs";

const WRITE = process.argv.includes("--write");
const ROOT = "workspace/src";
const files = globSync("**/*.{ts,html}", { cwd: ROOT }).map(f => ROOT + "/" + f.replaceAll("\\", "/"));

// Elements whose component has the renamed input (PillComponent + subclasses).
const RENAME_TAGS = new Set(["app-pill", "app-fancy-pill", "app-status-pill"]);
const tagRe = /<([a-zA-Z][\w-]*)\b((?:[^>"']|"[^"]*"|'[^']*')*?)\/?>/g;

let renamed = 0, kept = 0;
for (const file of files) {
    const src = readFileSync(file, "utf8");
    if (!src.includes(".disableTooltip()")) continue;

    // Map every template ref name (#name) to the tag it sits on.
    const refTag = new Map();
    for (const [, tag, attrs] of src.matchAll(tagRe)) {
        for (const [, name] of attrs.matchAll(/#([\w-]+)/g)) refTag.set(name, tag);
    }

    const out = src.replace(/\b([\w$]+)\.disableTooltip\(\)/g, (m, ref) => {
        const tag = refTag.get(ref);
        if (tag && RENAME_TAGS.has(tag)) { renamed++; return `${ref}.hideHint()`; }
        console.log(`  keep  ${file}  ${ref} -> <${tag ?? "?"}>`);
        kept++;
        return m;
    });
    if (WRITE && out !== src) writeFileSync(file, out);
}
console.log(`${renamed} ref reads renamed, ${kept} kept (${WRITE ? "written" : "dry run"})`);

