import { readFileSync, globSync } from "node:fs";

const ROOT = "workspace/src";
const files = globSync("**/*.{ts,html,css}", { cwd: ROOT }).map(f => ROOT + "/" + f.replaceAll("\\", "/"));
const PILL_TAGS = new Set(["app-pill", "app-fancy-pill", "app-status-pill"]);
const tagRe = /<([a-zA-Z][\w-]*)\b((?:[^>"']|"[^"]*"|'[^']*')*?)\/?>/g;
const attrRe = /([^\s=/>]+)(\s*=\s*(?:"[^"]*"|'[^']*'|[^\s>]*))?/g;

const buckets = new Map();
const add = (k, v) => { if (!buckets.has(k)) buckets.set(k, []); buckets.get(k).push(v); };

for (const file of files) {
    const src = readFileSync(file, "utf8");
    if (!src.includes("disableTooltip")) continue;
    const lineOf = i => src.slice(0, i).split("\n").length;

    // 1. attribute-name occurrences, bucketed by enclosing tag
    const attrHits = new Set();
    for (const tm of src.matchAll(tagRe)) {
        const tag = tm[1], attrs = tm[2], base = tm.index + 1 + tag.length;
        for (const am of attrs.matchAll(attrRe)) {
            const name = am[1];
            if (name === "disableTooltip" || name === "[disableTooltip]") {
                const pos = base + am.index;
                attrHits.add(lineOf(pos));
                add(PILL_TAGS.has(tag) ? `!! ATTR ON PILL TAG <${tag}>` : `attr on <${tag}>`, `${file}:${lineOf(pos)}`);
            }
        }
    }

    // 2. everything else, line by line
    src.split("\n").forEach((line, i) => {
        if (!line.includes("disableTooltip")) return;
        const ln = i + 1;
        const t = line.trim();
        let kind;
        if (/setInput\(\s*["']disableTooltip["']/.test(line)) kind = "!! setInput string";
        else if (/\[disableTooltip\]|\bapp-[\w-]*\[disableTooltip\]/.test(line) && file.endsWith(".css")) kind = "!! css selector";
        else if (/\.disableTooltip\b/.test(line)) kind = "!! member read";
        else if (/^(\/\/|\*|\/\*|<!--)/.test(t)) kind = "comment";
        else if (/@Input\(\)\s*disableTooltip|readonly disableTooltip\s*=|^\s*disableTooltip\s*=/.test(line)) kind = "own field decl";
        else if (attrHits.has(ln)) return; // already bucketed above
        else kind = "other (text / own-field expression)";
        add(kind, `${file}:${ln}  ${t.slice(0, 110)}`);
    });
}

for (const [k, v] of [...buckets].sort()) {
    console.log(`\n### ${k}  (${v.length})`);
    const show = k.startsWith("!!") || v.length <= 6 ? v : v.slice(0, 4).concat(`... +${v.length - 4} more`);
    show.forEach(s => console.log("  " + s));
}

